function validate([s, t]) {
  if (s.length < 1 || s.length > 100000) return 's has 1 to 10^5 letters.';
  if (t.length < 1 || t.length > 100000) return 't has 1 to 10^5 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase English letters.';
  return null;
}

