function longestCommonPrefix(s, t) {
  let i = 0;
  let j = 0;
  let removed = false;
  while (i < s.length && j < t.length) {
    if (s[i] === t[j]) {
      i++;
      j++;
    } else if (!removed) {
      removed = true;
      i++;
    } else {
      break;
    }
  }
  return j;
}

