function longestCommonPrefix(s, t) {
  // Try keeping s whole, then deleting each position in turn, and measure the common prefix each time.
  let best = 0;
  for (let skip = -1; skip < s.length; skip++) {
    const kept = skip < 0 ? s : s.slice(0, skip) + s.slice(skip + 1);
    let length = 0;
    while (length < kept.length && length < t.length && kept[length] === t[length]) length++;
    best = Math.max(best, length);
  }
  return best;
}

