function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const large = size === 'large';
  const letters = ['ab', 'abc', 'abcdefghijklmnopqrstuvwxyz'][pick(3)];
  const word = (length) => Array.from({ length }, () => letters[pick(letters.length)]).join('');
  const t = word(large ? 9000 + pick(1000) : 1 + pick(8));
  const style = pick(4);
  if (style === 0) return [word(large ? 9000 + pick(1000) : 1 + pick(8)), t];
  // Otherwise s is t with one extra letter, sometimes with a later letter changed or its end cut off.
  const at = pick(t.length + 1);
  let s = t.slice(0, at) + letters[pick(letters.length)] + t.slice(at);
  if (style === 2) {
    const q = pick(s.length);
    s = s.slice(0, q) + letters[pick(letters.length)] + s.slice(q + 1);
  }
  if (style === 3) s = s.slice(0, 1 + pick(s.length));
  return [s, t];
}
